package org.sleepwell.app;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.*;
import android.provider.Settings;
import android.widget.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;

/** Reviewed dated sleep shifts. Save affects silent reminders; wake alarms require their own Save. */
public final class TripSleepActivity extends Activity {
    private TripSleepPlan draft;private boolean resumed,opening;private String notice="",token="",pendingAlarm="",pendingZone="",pendingPlan="";private long pendingWake;private int generation;private Dialog dialog;
    private final Handler handler=new Handler(Looper.getMainLooper());private final ExecutorService reader=Executors.newSingleThreadExecutor();private final Runnable poll=this::observe;
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);try{TravelPlan trip=TravelPlans.repository(this).load(System.currentTimeMillis());if(trip.revision<=0)throw new IllegalStateException("Save your trip in Travel mode before planning sleep shifts.");TripSleepPlan saved=new TripSleepStore(this).load();if(saved!=null&&saved.matches(trip))draft=saved;else{draft=TripSleepPlan.initial(trip,SleepPlans.load(this));draft.earlier=trip.differenceSeconds(trip.departureAnchor())>0;if(saved!=null){draft.revision=saved.revision;notice="The trip changed. Review these dates and save to replace the previous sleep schedule.";}}if(state!=null){token=state.getString("token","");notice=state.getString("notice",notice);if(state.containsKey("draft")){TripSleepPlan restored=TripSleepPlan.decode(new org.json.JSONObject(state.getString("draft")));if(restored.matches(trip))draft=restored;else notice="The trip changed while this screen was closed. Review the new dates.";}pendingAlarm=state.getString("pendingAlarm","");pendingZone=state.getString("pendingZone","");pendingPlan=state.getString("pendingPlan","");pendingWake=state.getLong("pendingWake");}render();}catch(Exception invalid){draft=null;unavailable(invalid.getMessage());}}
    private void unavailable(String error){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Travel sleep schedule",this::finish);Design.text(body,error==null?"The travel sleep schedule could not be opened.":error,15,400,Design.MUTED);Design.button(body,"Open Travel mode",true,()->{startActivity(RecordUi.intent(this,TravelActivity.class));finish();});}
    private void render(){if(draft==null)return;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Travel sleep schedule",this::finish);Design.space(body,10);Design.text(body,"Before departure",24,600,Design.INK);Design.space(body,5);Design.text(body,draft.departure+" · "+TravelPlan.city(draft.home)+" → "+TravelPlan.city(draft.destination),13,400,Design.MUTED);Design.space(body,14);
        PlanActivity.detail(body,"bed","Usual bedtime",draft.home,Design.clock(this,draft.bed),()->chooseTime(true));Design.line(body);PlanActivity.detail(body,"sun","Usual wake-up",draft.home,Design.clock(this,draft.wake),()->chooseTime(false));Design.line(body);Design.space(body,14);
        Design.text(body,"Move your schedule",15,600,Design.INK);RecordUi.segments(body,new String[]{"Earlier","Later"},draft.earlier?0:1,n->{draft.earlier=n==0;render();});Design.space(body,10);PlanActivity.detail(body,"clock","Daily change",null,draft.step+" min",()->choices("Daily change",new String[]{"15 minutes","30 minutes","60 minutes"},draft.step==15?0:draft.step==30?1:2,n->{draft.step=new int[]{15,30,60}[n];render();}));Design.line(body);PlanActivity.detail(body,"calendar","Days before departure",null,draft.days+(draft.days==1?" day":" days"),()->{String[] labels=new String[7];for(int n=0;n<7;n++)labels[n]=(n+1)+(n==0?" day":" days");choices("Days before departure",labels,draft.days-1,n->{draft.days=n+1;render();});});Design.line(body);Design.space(body,16);
        Design.text(body,"Your dated plan",19,600,Design.INK);Design.space(body,6);Design.text(body,"Bedtime and wake-up shift together. Times below use "+draft.home+"; clock changes can alter the elapsed sleep window.",12,400,Design.MUTED);Design.space(body,10);try{for(TripSleepPlan.Night night:draft.nights()){LinearLayout card=Design.col(this);Design.pad(card,14,12);card.setBackground(Design.shape(this,Design.SOFT,14));ZoneId home=ZoneId.of(draft.home),target=ZoneId.of(draft.destination);Design.text(card,RecordUi.date(night.bed,home)+" · "+Math.abs(night.shift)+" min "+(night.shift<0?"earlier":"later"),14,600,Design.INK);Design.space(card,5);Design.text(card,"Bed "+RecordUi.clock(this,night.bed,home)+"  →  "+RecordUi.date(night.wake,home)+" "+RecordUi.clock(this,night.wake,home),15,600,Design.INK);Design.space(card,4);Design.text(card,"Destination: "+RecordUi.date(night.bed,target)+" "+RecordUi.clock(this,night.bed,target)+" → "+RecordUi.clock(this,night.wake,target),11,400,Design.MUTED);Design.text(card,"Elapsed window: "+RecordUi.duration(night.wake-night.bed),11,400,Design.MUTED);if(night.wake>System.currentTimeMillis()+60000)Design.button(card,"Create wake-up alarm draft",false,()->prepareAlarm(night));body.addView(card);Design.space(body,8);}}catch(RuntimeException invalid){Design.text(body,invalid.getMessage(),13,500,Design.BROWN);}
        Design.space(body,8);Design.toggle(body,"Bedtime reminders for these dates","Silent notifications only · Android may deliver late",draft.reminders,on->{draft.reminders=on;render();});if(draft.reminders)PlanActivity.detail(body,"bell","Remind before bedtime",null,draft.lead==0?"At bedtime":draft.lead+" min",()->choices("Reminder advance",new String[]{"At bedtime","15 minutes","30 minutes","60 minutes"},draft.lead==0?0:draft.lead==15?1:draft.lead==30?2:3,n->{draft.lead=new int[]{0,15,30,60}[n];render();}));Design.space(body,10);Design.text(body,"Review the direction and dates for your own trip. This is a schedule you choose; it does not measure your body clock or prescribe light, medication or a treatment. Existing alarms change only if you separately save an alarm draft.",12,400,Design.MUTED);Design.item(body,"info","About shifting sleep before travel",null,()->startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://www.cdc.gov/yellow-book/hcp/travel-air-sea/jet-lag-disorder.html"))));
        TripSleepStore store=new TripSleepStore(this);String status=store.prefs.getString("status","");if(!status.isEmpty())Design.text(body,status,12,400,Design.MUTED);String last=store.prefs.getString("lastDelivery","");if(!last.isEmpty())Design.text(body,last,12,400,Design.MUTED);String issue=!notice.isEmpty()?notice:store.error();if(!issue.isEmpty())Design.text(body,issue,13,500,Design.BROWN);if(draft.reminders&&!TripSleepRuntime.allowed(this))Design.button(body,"Allow reminder notifications",false,this::notifications);LinearLayout footer=RecordUi.footer(body);Design.button(footer,token.isEmpty()?"Save travel sleep schedule":"Saving…",true,this::save);if(!token.isEmpty()||opening){RecordUi.enabled(body,false);RecordUi.enabled(footer,false);}}
    private void chooseTime(boolean bed){if(!token.isEmpty()||dialog!=null&&dialog.isShowing())return;dialog=SleepPicker.time(this,bed?"Usual bedtime":"Usual wake-up",bed?draft.bed:draft.wake,n->{if(bed)draft.bed=n;else draft.wake=n;render();});}
    private void choices(String title,String[] labels,int selected,java.util.function.IntConsumer choose){if(!token.isEmpty()||dialog!=null&&dialog.isShowing())return;dialog=SleepPicker.choices(this,title,labels,selected,choose);}
    private void notifications(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},747);return;}startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));}
    private void save(){if(!resumed||!hasWindowFocus()||!token.isEmpty()||opening)return;try{draft.nights();if(draft.reminders&&!TripSleepRuntime.allowed(this)){notice="Allow notifications or turn bedtime reminders off before saving.";render();return;}token=UUID.randomUUID().toString();notice="";render();observe();}catch(RuntimeException invalid){notice=invalid.getMessage();render();}}
    private void observe(){if(!resumed||draft==null||token.isEmpty())return;TripSleepPlan snapshot=draft.copy();PlanOperations.Operation op=PlanOperations.start(this,token,app->{TripSleepRuntime.save(app,snapshot);return null;});if(!op.done){handler.postDelayed(poll,75);return;}PlanOperations.forget(token);token="";if(op.error!=null){notice=op.error;try{TripSleepPlan stored=new TripSleepStore(this).load();if(draft.sameChoices(stored))draft=stored;}catch(RuntimeException unreadable){notice+=" Reopen the plan before saving again.";}}else{draft=new TripSleepStore(this).load();notice="Travel sleep schedule saved. Wake alarms require their own Save.";}render();}
    private void prepareAlarm(TripSleepPlan.Night night){if(!resumed||!hasWindowFocus()||opening||!token.isEmpty())return;try{TripSleepPlan saved=new TripSleepStore(this).load();if(saved==null||!saved.json().toString().equals(draft.json().toString())||!saved.matches(TravelPlans.repository(this).load(System.currentTimeMillis())))throw new IllegalStateException("Save this travel sleep schedule before creating a wake-up alarm draft.");long wake=night.wake;String zone=ZoneId.systemDefault().getId(),plan=draft.json().toString();int request=++generation;opening=true;notice="Preparing an alarm draft…";render();reader.execute(()->{try(Store store=Records.factory.open(getApplicationContext())){ZonedDateTime local=Instant.ofEpochMilli(wake).atZone(ZoneId.of(zone));if(wake<=System.currentTimeMillis()+60000||AlarmDate.at(local.toLocalDate(),local.getHour(),local.getMinute(),ZoneId.of(zone))!=wake)throw new IllegalStateException("This wake time passed or is ambiguous in the phone's time zone.");Alarm alarm=HomeLaunch.draft(getApplicationContext(),store);alarm.hour=local.getHour();alarm.minute=local.getMinute();alarm.date=local.toLocalDate();alarm.days.clear();alarm.nap=null;alarm.solar=null;alarm.skip=null;alarm.excludedDates=Collections.unmodifiableSortedSet(new TreeSet<>());alarm.label="Travel wake-up";alarm.enabled=true;String json=alarm.json().toString();runOnUiThread(()->{if(isDestroyed()||request!=generation)return;opening=false;pendingAlarm=json;pendingWake=wake;pendingZone=zone;pendingPlan=plan;launchAlarm();});}catch(Exception failure){runOnUiThread(()->{if(isDestroyed()||request!=generation)return;opening=false;notice=failure.getMessage()==null?"The alarm draft could not be prepared.":failure.getMessage();render();});}});}catch(Exception invalid){notice=invalid.getMessage();render();}}
    private void launchAlarm(){if(pendingAlarm.isEmpty()||!resumed||!hasWindowFocus())return;String json=pendingAlarm;pendingAlarm="";try{TripSleepPlan saved=new TripSleepStore(this).load();if(saved==null||!saved.json().toString().equals(pendingPlan)||!saved.matches(TravelPlans.repository(this).load(System.currentTimeMillis()))||!ZoneId.systemDefault().getId().equals(pendingZone)||pendingWake<=System.currentTimeMillis()+60000)throw new IllegalStateException("The trip, clock or schedule changed. Review the alarm time again.");startActivity(new Intent(this,AlarmEditorActivity.class).putExtra("alarm",json));notice="Review the dated time in the alarm editor, then Save alarm. Phone time-zone changes can move a local-clock alarm.";}catch(Exception invalid){notice=invalid.getMessage();}render();}
    @Override protected void onResume(){super.onResume();resumed=true;observe();launchAlarm();}
    @Override protected void onPause(){resumed=false;handler.removeCallbacks(poll);super.onPause();}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused){RecordUi.lightBars(this);launchAlarm();}}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==747){notice=grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED?"Notifications allowed. Save the schedule to enable reminders.":"Notifications are blocked. Turn reminders off or enable them in Android settings.";render();}}
    @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(draft!=null)try{state.putString("draft",draft.json().toString());}catch(Exception ignored){}state.putString("token",token);state.putString("notice",notice);state.putString("pendingAlarm",pendingAlarm);state.putString("pendingZone",pendingZone);state.putString("pendingPlan",pendingPlan);state.putLong("pendingWake",pendingWake);}
    @Override public void finish(){if(token.isEmpty())super.finish();}
    @Override protected void onDestroy(){generation++;handler.removeCallbacksAndMessages(null);reader.shutdown();if(dialog!=null)dialog.dismiss();super.onDestroy();}
}
